[26656]={name="Черный киражский боевой танк",lore="Многие виды киражских боевых танков можно найти в руинах Ан'Киража, однако самые темные особи исчезли после того, как прогремел гонг Скарабея."},
[470]={name="Вороной жеребец",lore="По слухам, агенты ШРУ предпочитают использовать этих лошадей для ночных вылазок из-за их темной шерсти.",vendor="Кати Охотница"},
[22718]={name="Черный боевой кодо",lore="В кор'кронских стойлах этих животных разводят исключительно из-за непредсказуемого поведения и агрессии. Топот черного боевого кодо возвещает о том, что скоро прольется кровь.",vendor="Налетчик Борк"},
[22720]={name="Черный боевой баран",lore="Дворфы ценят своих верховых баранов за бесстрашие, с которым те несутся в битву.",vendor="Лейтенант Картер"},
[22721]={name="Черный боевой ящер",lore="Эта порода является преемником злобных ящеров, сородичей Огана, которые принесли победу империи Гурубаши.",vendor="Налетчик Борк"},
[22717]={name="Вороной боевой скакун",lore="Скакуны, обученные выдерживать самые свирепые схватки в ближнем бою.",vendor="Лейтенант Картер"},
