[22724]={name="Черный боевой волк",lore="Эти волки ценятся стражниками Оргриммара за превосходный нюх.",vendor="Налетчик Борк"},
[10969]={name="Синий механодолгоног",lore="\"Террадинамические экзоплоттеры соединяются с равновесными усилителями гидравлической системой...\" – Бинджи Перосвист.",vendor="Милли Перосвист"},
