[17462]={name="Красный конь-скелет",lore="Отрекшиеся верят, что даже скитающиеся вьючные звери страдают, будучи нежитью.",vendor="Захария Пост"},
[22722]={name="Красный боевой конь-скелет",lore="Когда павших героев обращают в нежить, та же участь постигает и их скакунов.",vendor="Налетчик Борк"},
[17481]={name="Конь смерти Ривендера",lore="Когда барон Ривендер стал командиром Плети, он обрек своего любимого коня на службу ему в мире нежити.",drop="Барон Ривендер"},
[10789]={name="Пятнистый ледопард",lore="Из-за своего ненасытного аппетита эти животные получили прозвище, которое на языке ночных эльфов означает \"драконье брюхо\".",vendor="Леланай"},
[23510]={name="Боевой скакун клана Грозовой Вершины",lore="У учителей верховой езды клана Грозовой Вершины есть традиция: они гравируют свои имена на левом роге каждого выращенного ими барана.",vendor="Гаелден Кузнечный Молот"},
[8394]={name="Полосатый ледопард",lore="Из-за своего ненасытного аппетита эти животные получили прозвище, которое на языке ночных эльфов означает \"драконье брюхо\".",vendor="Леланай"},
[10793]={name="Полосатый ночной саблезуб",lore="Саблезубы недаром считаются одними из лучших хищников Азерота: эти ловкие охотники могут пробираться через густые леса, не издавая ни звука.",vendor="Леланай"},
[23241]={name="Стремительный синий ящер",lore="Давние союзники троллей, эти охотники джунглей создают особую связь со своим наездником. Они становятся не просто ездовым животным, а другом и защитником.",vendor="Зьольнир"},
[23238]={name="Стремительный бурый баран",lore="У баранов Барак Торола толстый череп и массивные рога, что помогает им с легкостью таранить отряды бронированных врагов.",vendor="Верон Янтарлен"},
[23229]={name="Стремительный гнедой рысак",lore="Ветеран, закаленный в самых тяжелых боях Серебряного Авангарда.",vendor="Кати Охотница"},
[23250]={name="Стремительный бурый волк",lore="Волки Орды – это союзники, а не прирученные звери.",vendor="Огунаро Волкопас"},
[23221]={name="Стремительный ледопард",lore="Ночные эльфы выращивают котят ледопарда с раннего детства, создавая между наездником и зверем нерушимые узы доверия длиною в жизнь.",vendor="Леланай"},
[23239]={name="Стремительный серый баран",lore="У баранов Барак Торола толстый череп и массивные рога, что помогает им с легкостью таранить отряды бронированных врагов.",vendor="Верон Янтарлен"},
[23252]={name="Стремительный серый волк",lore="Волки Орды – это союзники, а не прирученные звери.",vendor="Огунаро Волкопас"},
[23225]={name="Стремительный зеленый механодолгоног",lore="\"Мы внесли множество улучшений, но они все еще основаны на чертежах Меггакрута\", – Милли Перосвист.",vendor="Милли Перосвист"},
[23219]={name="Стремительный туманный саблезуб",lore="Некоторые историки считают, что эта порода получила свою туманную серую шкуру в ходе экспериментов древних высокорожденных над ночными саблезубами.",vendor="Леланай"},
[23242]={name="Стремительный оливковый ящер",lore="Давние союзники троллей, эти охотники джунглей создают особую связь со своим наездником. Они становятся не просто ездовым животным, а другом и защитником.",vendor="Зьольнир"},
[23243]={name="Стремительный оранжевый ящер",lore="Давние союзники троллей, эти охотники джунглей создают особую связь со своим наездником. Они становятся не просто ездовым животным, а другом и защитником.",vendor="Зьольнир"},
[23227]={name="Стремительный игреневый конь",lore="Коневоды ценят эту породу за выдержку и стойкость.",vendor="Кати Охотница"},
[24242]={name="Стремительный ящер Раззаши",lore="Единственные известные в природе ящеры Раззаши содержались в Зул'Гурубе под опекой Мандокира Повелителя Крови. Эту породу никто не видел уже много лет.",drop="Мандокир Повелитель Крови"},
[23338]={name="Стремительный грозовой саблезуб",lore="По слухам, эта порода получила название в честь любимого заклинания шаманов.",vendor="Леланай"},
[23251]={name="Стремительный лесной волк",lore="Волки Орды – это союзники, а не прирученные звери.",vendor="Огунаро Волкопас"},
[23223]={name="Стремительный белый механодолгоног",lore="\"Мы внесли множество улучшений, но они все еще основаны на чертежах Меггакрута\", – Милли Перосвист.",vendor="Милли Перосвист"},
[23240]={name="Стремительный белый баран",lore="У баранов Барак Торола толстый череп и массивные рога, что помогает им с легкостью таранить отряды бронированных врагов.",vendor="Верон Янтарлен"},
[23228]={name="Стремительный белый рысак",lore="Ветеран, закаленный в самых тяжелых боях Серебряного Авангарда.",vendor="Кати Охотница"},
[23222]={name="Стремительный желтый механодолгоног",lore="\"Мы внесли множество улучшений, но они все еще основаны на чертежах Меггакрута\", – Милли Перосвист.",vendor="Милли Перосвист"},
[24252]={name="Стремительный зульский тигр",lore="Последние зульские тигры жили в Зул'Гурубе – под покровительством верховного жрец Текала. Говорят, что сейчас их уже истребили полностью.",drop="Верховный жрец Текал"},
[580]={name="Лесной волк",lore="Вой этого волка разносится на километры вокруг.",vendor="Огунаро Волкопас"},
[10796]={name="Бирюзовый ящер",lore="Эта порода выведена из самых свирепых особей. Заводчики гарантируют, что они не кусаются (ну, разве что иногда).",vendor="Зьольнир"},
[17454]={name="Некрашеный механодолгоног",lore="\"Террадинамические экзоплоттеры соединяются с равновесными усилителями гидравлической системой...\" – Бинджи Перосвист.",vendor="Милли Перосвист"},
[10799]={name="Фиолетовый ящер",lore="Эта порода выведена из самых свирепых особей. Заводчики гарантируют, что они не кусаются (ну, разве что иногда).",vendor="Зьольнир"},
[13819]={name="Боевой конь",lore="Скакун, обученный упорству в праведном бою."},
[6898]={name="Белый баран",lore="Самцы баранов могут часами бодаться, чтобы впечатлить самку. В этом отношении они очень похожи на дворфов.",vendor="Верон Янтарлен"},
[17229]={name="Ледопард Зимних Ключей",lore="Укрощение этой дикой породы потребует терпения, силы и огромного запаса игрушечных мышек на веревочках.",vendor="Риверн Холодный Ветер"},
[26055]={name="Желтый киражский боевой танк",lore="Эти сравнительно одомашненные силитиды чувствуют себя как дома только в пустынных песках Ан'Киража."},
}]=])())
